arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"exclude_archived": false, "types": "public_channel,private_channel", "limit": 1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error'), d.get('response_metadata',{}))
    sys.exit(0)
for c in d.get('channels', []):
    if 'checkout' in c.get('name','').lower() or 'outage' in c.get('name','').lower() or 'outage' in (c.get('topic') or {}).get('text','').lower():
        print(c.get('id'), c.get('name'), '| archived:', c.get('is_archived'), '| topic:', (c.get('topic') or {}).get('text'))
"

